const K2=0.01720209895*0.01720209895;
function chironHelio(jd){
  let lo=0,hi=CHI.length-1;if(jd<CHI[0][0]-CHI[0][1]-1||jd>CHI[hi][0]+CHI[hi][1]+1)return null;
  while(hi-lo>1){const m=(lo+hi)>>1;if(CHI[m][0]<=jd)lo=m;else hi=m;}
  const S=Math.abs(jd-CHI[lo][0])<=CHI[lo][1]?CHI[lo]:CHI[hi];
  const [m,h,a,e,i,Om,w,M0,cx,cy,cz]=S,x=Math.max(-1,Math.min(1,(jd-m)/h));
  const M=M0+Math.sqrt(K2/(a*a*a))*(jd-m);let E=M;for(let k=0;k<30;k++)E-=(E-e*Math.sin(E)-M)/(1-e*Math.cos(E));
  const xp=a*(Math.cos(E)-e),yp=a*Math.sqrt(1-e*e)*Math.sin(E),cw=Math.cos(w),sw=Math.sin(w),cO=Math.cos(Om),sO=Math.sin(Om),ci=Math.cos(i),si=Math.sin(i);
  const cheb=c=>{let b1=0,b2=0;for(let k=c.length-1;k>=1;k--){const t=2*x*b1-b2+c[k];b2=b1;b1=t;}return (x*b1-b2+c[0])/1e5;};
  return[(cw*cO-sw*sO*ci)*xp+(-sw*cO-cw*sO*ci)*yp+cheb(cx),(cw*sO+sw*cO*ci)*xp+(-sw*sO+cw*cO*ci)*yp+cheb(cy),(sw*si)*xp+(cw*si)*yp+cheb(cz)];
}
