    +0.000691*E*S(2*D+M-2*Mp)+0.000596*E*S(2*D-M-2*F)+0.000549*S(4*D+Mp)+0.000537*S(4*Mp)
    +0.000520*E*S(4*D-M)-0.000487*S(D-2*Mp)-0.000399*E*S(2*D+M-2*F)-0.000381*S(2*Mp-2*F)
