  if(body==='chiron'){const e=earthAt(T),p=chironHelio(jd);if(!p)return NaN;
    const lt=Math.hypot(p[0]-e[0],p[1]-e[1],p[2]-e[2])*0.0057755,p2=chironHelio(jd-lt);
    return norm(precVec([p2[0]-e[0],p2[1]-e[1],p2[2]-e[2]],T)+nut(T));}
